import fs from "node:fs/promises";
import {
  Presentation,
  PresentationFile,
  layers,
  shape,
  text,
} from "@oai/artifact-tool";

const OUT = "C:/Users/User/Documents/ChatGPT/Muc Legal LLT Hackathon/output/MucLegal_Zwei_Folien_Juristen.pptx";
const RENDER_DIR = "C:/Users/User/Documents/ChatGPT/Muc Legal LLT Hackathon/tmp/juristen-folien-v1/rendered";

const C = {
  ink: "#000000",
  muted: "#5F6670",
  panel: "#EDEDED",
  rule: "#B8BCC4",
  accent: "#6DCBF4",
  accentStrong: "#3D8DFF",
  white: "#FFFFFF",
};

function para(run, size, options = {}) {
  return {
    runs: [{
      run,
      textStyle: {
        fontSize: `${size}px`,
        typeface: options.typeface || "Arial",
        color: options.color || C.ink,
        bold: options.bold || false,
      },
    }],
    spaceAfter: options.spaceAfter ?? 650,
    paragraphStyle: {
      lineSpacingPercent: options.lineSpacingPercent || 110000,
      bullet: options.bullet,
    },
  };
}

function titleBlock(title) {
  return para(title, 46, { bold: true, spaceAfter: 0, lineSpacingPercent: 95000 });
}

function stepBlock(number, heading, body) {
  return [
    para(number, 17, { bold: true, color: C.accentStrong, spaceAfter: 350 }),
    para(heading, 30, { bold: true, spaceAfter: 550 }),
    para(body, 21.33, { color: C.muted, spaceAfter: 0, lineSpacingPercent: 112000 }),
  ];
}

function addTitle(slide, title, number) {
  slide.compose(
    layers({ name: `slide-${number}-chrome`, width: "fill", height: "fill" }, [
      shape({
        name: `title-rule-${number}`,
        geometry: "rect",
        position: { left: 42, top: 148, width: 1196, height: 2 },
        fill: C.ink,
        line: { style: "solid", width: 0, fill: "none" },
      }),
      text([titleBlock(title)], {
        name: `title-${number}`,
        position: { left: 42, top: 38 },
        width: 1196,
        height: 92,
        style: {
          fontSize: "46px",
          typeface: "Arial",
          color: C.ink,
          alignment: "left",
          verticalAlignment: "top",
          autoFit: "shrinkText",
          insets: { top: 0, right: 0, bottom: 0, left: 0 },
        },
      }),
      text([para(String(number).padStart(2, "0"), 13.33, { spaceAfter: 0 })], {
        name: `page-${number}`,
        position: { left: 1184, top: 671 },
        width: 54,
        height: 20,
