        line: { style: "solid", width: 1, fill: C.accent },
      }),
      text([
        para("So entsteht der Hash", 31, { bold: true, spaceAfter: 900 }),
        para("1. Öffentliche Seite abrufen", 21.33, { spaceAfter: 450 }),
        para("2. Störwerte entfernen – etwa Cookie-Banner, Session-IDs und Zeitstempel", 21.33, { spaceAfter: 450 }),
        para("3. SHA-256 über den normalisierten Text bilden", 21.33, { spaceAfter: 0 }),
      ], {
        name: "hash-explanation",
        position: { left: 42, top: 194 }, width: 560, height: 215,
        style: { fontSize: "21.33px", typeface: "Arial", color: C.ink, autoFit: "shrinkText", insets: { top: 0, right: 8, bottom: 0, left: 0 } },
      }),
      text([
        para("SHA-256", 17, { bold: true, color: C.accentStrong, spaceAfter: 400 }),
        para("7f2a…91c4", 30, { bold: true, typeface: "Consolas", spaceAfter: 0 }),
      ], {
        name: "hash-example",
        position: { left: 62, top: 442 }, width: 520, height: 60,
        style: { fontSize: "24px", typeface: "Arial", color: C.ink, insets: { top: 0, right: 0, bottom: 0, left: 0 } },
      }),
      text([
        para("So werden Unterseiten überwacht", 31, { bold: true, spaceAfter: 900 }),
        para("• Relevante URLs werden gezielt hinterlegt: Startseite, Produktseite, Checkout-Hinweis oder Kampagnenseite.", 21.33, { spaceAfter: 650 }),
        para("• Jede URL erhält ihre eigene Ausgangsfassung – ihre Baseline.", 21.33, { spaceAfter: 650 }),
        para("• Täglicher Vergleich: gleicher Hash → Ende; neuer Hash → Klauselvergleich und Tenorprüfung.", 21.33, { spaceAfter: 650 }),
        para("Keine automatische Webseitensuche: Der juristisch relevante Beobachtungsumfang wird bewusst festgelegt.", 18.5, { color: C.muted, spaceAfter: 0 }),
      ], {
        name: "subpage-explanation",
        position: { left: 658, top: 194 }, width: 580, height: 320,
        style: { fontSize: "21.33px", typeface: "Arial", color: C.ink, autoFit: "shrinkText", insets: { top: 0, right: 0, bottom: 0, left: 0 } },
      }),
      text([
        para("Warum juristisch belastbar?", 24, { bold: true, spaceAfter: 350 }),
        para("Der Hash allein beweist weder Inhalt noch Zeitpunkt. Belastbar wird er durch die dokumentierte Kette aus Original-HTML, Headern, Screenshot, WARC, Manifest/Hashkette und RFC-3161-Zeitstempel – plus menschlicher Freigabe.", 18.5, { spaceAfter: 0 }),
      ], {
        name: "legal-evidence-callout",
        position: { left: 62, top: 570 }, width: 1156, height: 68,
        style: { fontSize: "18.5px", typeface: "Arial", color: C.ink, autoFit: "shrinkText", insets: { top: 0, right: 0, bottom: 0, left: 0 } },
      }),
    ]),
    { frame: { left: 0, top: 0, width: 1280, height: 720 }, baseUnit: 1 },
  );

  slide.speakerNotes.textFrame.setText(
    "[Sources]\n" +
    "- Normalisierung und Hashbildung: muclegal/normalize/core.py; muclegal/pipeline.py.\n" +
    "- Beweiskette: muclegal/evidence/manifest.py; warc.py; timestamp.py; report.py.\n" +
    "- Scope-Grenze zur URL-Erkennung: AGENTS.md, Nicht-Ziele und bekannte Grenzen."
  );
  return slide;
}

async function writeBlob(path, blob) {
  await fs.writeFile(path, new Uint8Array(await blob.arrayBuffer()));
}

async function main() {
  await fs.mkdir(RENDER_DIR, { recursive: true });
  await fs.mkdir(new URL("../", `file:///${OUT.replaceAll("\\", "/")}`).pathname, { recursive: true }).catch(() => {});
  const presentation = Presentation.create({ slideSize: { width: 1280, height: 720 } });
  addPipelineSlide(presentation);
  addFingerprintSlide(presentation);

  for (const [index, slide] of presentation.slides.items.entries()) {
    const stem = `slide-${index + 1}`;
    await writeBlob(`${RENDER_DIR}/${stem}.png`, await presentation.export({ slide, format: "png", scale: 1 }));
    await fs.writeFile(`${RENDER_DIR}/${stem}.layout.json`, await (await slide.export({ format: "layout" })).text());
  }
  await writeBlob(`${RENDER_DIR}/montage.webp`, await presentation.export({ format: "webp", montage: true, scale: 1 }));
  const pptx = await PresentationFile.exportPptx(presentation);
  await pptx.save(OUT);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

